typedef struct {
    char id;
    int data[5];
} Config;

// Using Compound Literal (CL) for anonymous array initialization
void process_data(const int* arr) { /* ... */ }
process_data( (int[10]){ [0]=1, [9]=10 } );

// Using CL + Designated Initializers (DI) for dynamic struct setup
const Config* ref = &(Config){
    .id = 'C',
    .data = { [1]=42, [3]=84 } // Nested CL/DI
};

// Use temporary object for function arguments
float calculate(const Config* c);
float result = calculate( &(Config){ .id='Z', .data={[0]=1} } );
